// 物理HMCN由K9唯一编解码；这里只反读已选择原专业真实起点/停点，调用仍原run。
#include "exact_run_read.hpp"
#include "world_bundle.hpp"
#include "world_read_stamp.hpp"
#include <stdexcept>
#include <limits>
namespace hanmo::resident {
namespace {
struct Failure{RuleError error;};
void fail(const char* code){throw Failure{common_failure(code,"exact_run").error};}
template<class T>T take(Outcome<T> value){if(!value.ok)throw Failure{std::move(value.error)};return std::move(value.value);}
template<class T,class F>Outcome<T> guard(F fn){try{return {true,fn(),{}};}catch(Failure& e){return {false,{},std::move(e.error)};}catch(const std::bad_alloc&){return {false,{},common_failure("ExactRunReadResourceExhausted","exact_run",ErrorKind::internal).error};}catch(const std::length_error&){return {false,{},common_failure("ExactRunReadResourceExhausted","exact_run",ErrorKind::internal).error};}}
const ActionTimeRegistration& find(const CompleteExactTimeRuntime& runtime,const StableId& kind){const ActionTimeRegistration* result=nullptr;for(const auto& r:runtime.action_times)if(r.action_kind==kind){if(result)fail("DuplicateActionTimeRegistration");result=&r;}if(!result)fail("MissingActionTimeRegistration");return *result;}
WorldMoment current(const WorldBundle& world){if(!world.catalog->exact_time||!exact_complete_selected(*world.catalog->exact_time)||!world.world_timeline||!world.action_elapsed)fail("CompleteExactContinuationRequired");return take(read_world_moment(world.common.tick(),*world.world_timeline));}
ContinuationStartedSource started(const ActionTimeOwnerProof& proof){return std::visit([](const auto& source){if(source.source_schema<=0||static_cast<std::uint64_t>(source.source_schema)>std::numeric_limits<std::uint32_t>::max())fail("InvalidContinuationSourceSchema");return ContinuationStartedSource{source.source_ref.domain,source.source_ref.kind,source.source_ref.id,static_cast<std::uint32_t>(source.source_schema)};},proof.started_source);}
void identity(const ActionTimeOwnerProof& proof,const ContinuationSnapshot& snapshot){if(proof.action_ref!=snapshot.action_id||proof.action_kind!=snapshot.action_kind||proof.actor_id!=snapshot.actor_id)fail("ContinuationActionMismatch");}
}
bool complete_exact_run_kind(const CompleteExactTimeRuntime& runtime,const StableId& kind)noexcept{for(const auto& row:runtime.action_times)if(row.action_kind==kind)return true;return false;}
Outcome<ContinuationStartedSource> read_complete_exact_continuation_start(const WorldBundle& world,const CompleteExactWorldReadBindings& access,const StableId& action,const StableId& kind){return guard<ContinuationStartedSource>([&]{auto at=current(world);auto scope=take(world.enter_phase_read_context("continuation_source","world_timeline",{at,at},at));const auto& registration=find(access.runtime,kind);auto proof=take(access.action_sources.read_action_time_owner(registration,action));take(read_action_time_projection(registration,proof,*world.action_elapsed,at,world.world_timeline->scale_ref,access.action_sources));if(proof.action_ref!=action)fail("ContinuationActionMismatch");return started(proof);});}
Outcome<RunStop> read_complete_exact_continuation_stop(const WorldBundle& world,const CompleteExactWorldReadBindings& access,const ContinuationSnapshot& snapshot){return guard<RunStop>([&]{auto at=current(world);auto scope=take(world.enter_phase_read_context("continuation_stop","world_timeline",{at,at},at));const auto& registration=find(access.runtime,snapshot.action_kind);auto proof=take(access.action_sources.read_action_time_owner(registration,snapshot.action_id));identity(proof,snapshot);take(read_action_time_projection(registration,proof,*world.action_elapsed,at,world.world_timeline->scale_ref,access.action_sources));const auto* action=world.common.action(snapshot.action_id);const auto* actor=world.common.actor(snapshot.actor_id);if(!actor||!actor->alive)return RunStop::blocked;if(action&&(action->actor_id!=snapshot.actor_id||action->kind!=snapshot.action_kind))return RunStop::action_replaced;if(!actor->action_id.empty()&&actor->action_id!=snapshot.action_id)return RunStop::action_replaced;
    auto stop=take(access.action_sources.read_action_continuation_stop(registration,proof,at));switch(stop){case RunStop::awaiting_permit:if(!action||proof.phase!=ActionTimeOwnerPhase::working)fail("ContinuationOwnerCannotAdvance");break;case RunStop::arrived:case RunStop::completed:if(action||proof.phase!=ActionTimeOwnerPhase::terminal)fail("ContinuationFalseCompletion");break;case RunStop::awaiting_input:case RunStop::paused:case RunStop::stranded:case RunStop::blocked:case RunStop::cancelled:case RunStop::action_replaced:break;default:fail("InvalidOriginalContinuationStop");}return stop;
});}
Status validate_complete_exact_continuation_source(const WorldBundle& world,const CompleteExactWorldReadBindings& access,const ContinuationSnapshot& snapshot){return guard<Done>([&]{auto at=current(world);if(snapshot.continuation_version!=2||!snapshot.action_started_source||!snapshot.exact_source_moment||!snapshot.exact_started_at)fail("ExactContinuationRequired");if(take(compare_world_moments(at,*snapshot.exact_source_moment))!=0)fail("ContinuationSourceMismatch");auto scope=take(world.enter_phase_read_context("continuation_restore","world_timeline",{at,at},at));const auto& registration=find(access.runtime,snapshot.action_kind);auto proof=take(access.action_sources.read_action_time_owner(registration,snapshot.action_id));identity(proof,snapshot);auto projected=take(read_action_time_projection(registration,proof,*world.action_elapsed,at,world.world_timeline->scale_ref,access.action_sources));const auto original=started(proof);const auto& saved=*snapshot.action_started_source;if(original.domain!=saved.domain||original.kind!=saved.kind||original.id!=saved.id||original.schema!=saved.schema)fail("ContinuationActionStartMismatch");if(take(compare_world_moments(projected.started_at,*snapshot.exact_started_at))>0)fail("ContinuationActionStartMismatch");const auto* action=world.common.action(snapshot.action_id);if(!action||proof.phase==ActionTimeOwnerPhase::terminal||action->remaining_ticks!=projected.remaining_half_days||action->start_tick!=projected.started_at.half_day_tick||action->participants!=proof.participant_actor_ids)fail("ContinuationActionMismatch");return Done{};
});}
}
